package com.huy.enterprise.supplier; import com.huy.enterprise.common.enums.RiskLevel; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/suppliers") @RequiredArgsConstructor public class SupplierController {private final SupplierService service; @GetMapping List<SupplierResponse> all(@RequestParam(required=false) RiskLevel riskLevel){return service.all(riskLevel);}@GetMapping("/{id}") SupplierResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) SupplierResponse create(@Valid @RequestBody SupplierRequest r){return service.create(r);}@PutMapping("/{id}") SupplierResponse update(@PathVariable UUID id,@Valid @RequestBody SupplierRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){service.delete(id);}}
